#pragma pack(push, 1)
struct TraceFileHeader {
    char magic[8];
    std::uint32_t version;
    std::uint32_t pointerSize;
    std::uint32_t processId;
    std::uint32_t reserved;
};

struct TraceRecordWire {
    std::uint32_t magic;
    std::uint16_t version;
    std::uint16_t headerSize;
    std::uint64_t sequence;
    std::int64_t wallUnixMs;
    std::uint64_t qpc;
    std::uint32_t processId;
    std::uint32_t threadId;
    std::uint16_t api;
    std::uint16_t direction;
    std::uint32_t socketValue;
    std::int32_t callResult;
    std::uint32_t lastError;
    std::uint32_t requestedLength;
    std::uint32_t transferredLength;
    std::uint32_t capturedLength;
    std::uint32_t frame208;
    std::uint32_t flags;
    std::uint16_t localFamily;
    std::uint16_t remoteFamily;
    std::uint16_t localPort;
    std::uint16_t remotePort;
    unsigned char localAddress[16];
    unsigned char remoteAddress[16];
    std::uint32_t returnAddress;
    std::uint32_t stackDepth;
    std::uint32_t stack[kStackSlots];
};
#pragma pack(pop)

static_assert(sizeof(TraceRecordWire) == 188, "TraceRecordWire size must match analyzer.");
static_assert(sizeof(TraceFileHeader) == 24, "TraceFileHeader size must match analyzer.");

struct RingEntry {
    bool used;
    std::uint64_t parentSequence;
    std::uint64_t contextSequence;
    std::uint32_t callDepth;
    TraceRecordWire record;
    unsigned char payload[kMaxPayload];
};

