struct HookRecord {
    const char* dllName;
    const char* procName;
    void* target;
    unsigned char originalBytes[5];
    unsigned char originalEntryBytes[2];
    unsigned char originalPrefixBytes[5];
    unsigned char publishedPrefixBytes[5];
    DWORD originalProtection{};
    void* trampoline;
    bool installed;
    bool hotpatch;
    bool hotpatchPrefixPending{};
    void** publishedOriginalSlot{};
    void* publishedOriginalValue{};
    // A bridge original lives in the process-lifetime RW/NX arena and must
    // remain a valid pass-through after this DLL is unloaded.  Session-owned
    // wrapper/trampoline slots are still cleared during the release epoch.
    bool persistentOriginal{};
};

