// The packed state token is the sole publication/ownership word.  Every
// transition compares the complete epoch plus state so a delayed completion
// cannot consume a later transaction that reused the same fixed slot.
struct SensitiveOutboundTransaction {
    volatile LONG stateToken{};
    DWORD transactionId{};
    DWORD creatorThreadId{};
    DWORD lastOwnerThreadId{};
    DWORD producerFingerprint{};
    DWORD transportFingerprint{};
    DWORD frameLength{};
    DWORD remainingLength{};
    DWORD completedLength{};
    DWORD apiKind{};
    SOCKET socketValue{INVALID_SOCKET};
    std::uintptr_t expectedBuffer{};
    LPWSAOVERLAPPED overlapped{};
    DWORD bridgeCompletionSlot{MAXDWORD};
    LONG bridgeCompletionToken{};
    DWORD bridgeGeneration{};
    DWORD segmentCount{};
    SensitiveOutboundSegment segments[kMaxSensitiveOutboundBuffers]{};
};

struct SensitiveOutboundTableContext {
    SensitiveOutboundTransaction* entries{};
    DWORD capacity{};
    volatile LONG* transactionSequence{};
    volatile LONG* activeCount{};
    volatile LONG* createdCount{};
    volatile LONG* completedCount{};
    volatile LONG* retryCount{};
    volatile LONG* partialCount{};
    volatile LONG* pendingCount{};
    volatile LONG* crossThreadCompletionCount{};
    volatile LONG* ambiguousCount{};
    volatile LONG* unverifiableCount{};
    volatile LONG* capacityDrops{};
    volatile LONG* epochExhausted{};
    volatile LONG* staleCompletionCount{};
    volatile LONG* opaqueFailClosed{};
    // Private-fixture-only handoff. The production context is permanently
    // null, so no hook path spins or retains a DLL test pointer.
    volatile LONG* publicationBarrier{};
};

