// A process-owned, fixed-size bridge is deliberately kept outside this PE so
// a caller that is legitimately blocked in Winsock/IOCP never retains a return
// address into the probe DLL.  The bridge has one bounded arena per target
// process lifetime.  Code pages are sealed RX before publication; state pages
// remain RW/NX.  Repeated probe sessions reuse the same arena and generation.
constexpr std::uint32_t kBridgeMagic = 0x52423247u; // G2BR
constexpr std::uint32_t kBridgeAbiVersion = 1u;
constexpr DWORD kBridgePageBytes = 4096u;
constexpr DWORD kBridgeMaxRxPages = 3u;
constexpr DWORD kBridgeStatePages = 2u;
constexpr DWORD kBridgeTotalPages = kBridgeMaxRxPages + kBridgeStatePages;
constexpr DWORD kBridgeTotalBytes = kBridgeTotalPages * kBridgePageBytes;
constexpr DWORD kBridgeCompletionCapacity = 256u;
constexpr LONG kBridgeCompletionStateMask = 0x3;
constexpr LONG kBridgeCompletionTokenIncrement = 0x4;
constexpr DWORD kBridgeMaximumApis = 11u;
constexpr DWORD kBridgeEventScratchBytes = kMaxPayload;
constexpr std::uint32_t kBridgeCodeCanary = 0xC04E2B17u;
constexpr std::uint32_t kBridgeStateCanary = 0x51A7E0F1u;
constexpr std::uint32_t kBridgeObserverCommit = 0xC01117EDu;

enum class BridgePhase : LONG {
    Detached = 0,
    Arming = 1,
    Active = 2,
    Disarming = 3
};

enum class BridgeApi : std::uint32_t {
    Send = 0,
    WSASend = 1,
    Recv = 2,
    WSARecv = 3,
    WSAGetOverlappedResult = 4,
    GetQueuedCompletionStatus = 5,
    GetQueuedCompletionStatusEx = 6,
    WSARecvCompletionRoutine = 7,
    Parser = 8,
    Serializer = 9,
    Handler = 10,
    Count = kBridgeMaximumApis
};

enum class BridgeEventStage : std::uint32_t {
    BeforeOriginal = 0,
    AfterOriginal = 1,
    Completion = 2
};

struct BridgeEventV1 {
    std::uint32_t size{};
    std::uint32_t api{};
    std::uint32_t stage{};
    std::uint32_t generation{};
    std::uint32_t result{};
    std::uint32_t lastError{};
    std::uint32_t callerReturnAddress{};
    std::uint32_t thisPointer{};
    std::uint32_t argumentCount{};
    std::uint32_t arguments[7]{};
    std::uint32_t completionSlot{};
    std::uint32_t completionToken{};
    std::uint32_t observerStatus{};
    std::uint32_t entryLastError{};
    std::uint32_t scratchBytes{};
    std::uint32_t reserved{};
    unsigned char scratch[kBridgeEventScratchBytes]{};
};

using BridgeObserverFn = void(__stdcall*)(BridgeEventV1* event);

struct BridgeApiV1 {
    volatile LONG original{};
    volatile LONG entry{};
    volatile LONG preObserved{};
    volatile LONG postObserved{};
    volatile LONG installed{};
    volatile LONG restorable{};
};

enum class BridgeCompletionState : LONG {
    Free = 0,
    Reserved = 1,
    Armed = 2,
    Completing = 3
};

struct BridgeCompletionSlotV1 {
    volatile LONG state{};
    volatile LONG generation{};
    volatile LONG overlapped{};
    volatile LONG applicationCompletion{};
    volatile LONG thunk{};
};

struct BridgeArenaV1 {
    std::uint32_t magic{};
    std::uint32_t abiVersion{};
    std::uint32_t totalBytes{};
    std::uint32_t processId{};
    std::uint64_t processCreationTime{};
    std::uint32_t primaryCodeVa{};
    std::uint32_t primaryStateVa{};
    std::uint32_t maxRxPages{};
    volatile LONG actualRxPages{};
    volatile LONG codeBytes{};
    volatile LONG phase{};
    volatile LONG generation{};
    volatile LONG observerFn{};
    volatile LONG observerRundown{};
    volatile LONG preOriginalRundown{};
    volatile LONG bridgeFrames{};
    volatile LONG pendingApplicationCallbacks{};
    volatile LONG completionHighWater{};
    volatile LONG completionCapacityDrops{};
    volatile LONG completionIdentityMismatches{};
    volatile LONG completionEpochExhausted{};
    volatile LONG captureObserverRetired{};
    volatile LONG iatRestored{};
    volatile LONG hotpatchRestored{};
    volatile LONG stickyDynamicExposure{};
    volatile LONG writableExecutablePageCount{};
    std::uint32_t codeCanary{};
    std::uint32_t stateCanary{};
    unsigned char codeSha256[32]{};
    BridgeApiV1 apis[kBridgeMaximumApis]{};
    BridgeCompletionSlotV1 completions[kBridgeCompletionCapacity]{};
};

static_assert(sizeof(BridgeEventV1) == 4184u,
              "BridgeEventV1 is a versioned x86 wire structure.");
static_assert(offsetof(BridgeEventV1, scratch) == 88u,
              "BridgeEventV1 header zeroing must not touch saved registers.");
static_assert(sizeof(BridgeEventV1) % sizeof(DWORD) == 0u,
              "BridgeEventV1 stack allocation must be dword aligned.");
static_assert(sizeof(BridgeApiV1) == 24u,
              "BridgeApiV1 layout must remain fixed.");
static_assert(sizeof(BridgeCompletionSlotV1) == 20u,
              "BridgeCompletionSlotV1 layout must remain fixed.");
static_assert(sizeof(BridgeArenaV1) <= kBridgeStatePages * kBridgePageBytes,
              "Bridge state must fit the fixed RW/NX arena.");

