static_assert(_countof(kSemanticEventDefinitions) == 25,
              "God2SemanticEvent v2 requires 25 schema-defined producer paths.");

god2::shared::SemanticPriority schemaDefinedRequestPriority(
    const SchemaDefinedEventRequest& request) noexcept
{
    // Startup/candidate ProbeDiagnostic rows stay low priority.  A real
    // per-domain isolation fault is operational loss evidence and must retain
    // the P0 reserve even though its AuthorityHint remains UNKNOWN.
    if (request.definitionIndex == 24u && request.sourceToken != nullptr &&
        std::strcmp(request.sourceToken, "PerDomainFaultIsolation") == 0)
        return god2::shared::SemanticPriority::Authoritative;
    return request.definitionIndex < _countof(kSemanticEventDefinitions) ?
        kSemanticEventDefinitions[request.definitionIndex].priority :
        god2::shared::SemanticPriority::CandidateTelemetry;
}

