bool isCanonicalSha256(const char* value) noexcept
{
    if (value == nullptr || std::strlen(value) != 64u) return false;
    for (std::size_t index = 0; index < 64u; ++index) {
        const unsigned char ch = static_cast<unsigned char>(value[index]);
        if (!((ch >= '0' && ch <= '9') || (ch >= 'A' && ch <= 'F') ||
              (ch >= 'a' && ch <= 'f'))) return false;
    }
    return true;
}

// Never label evidence from an unverified process with the official build ID.
// A well-formed observed hash is useful provenance, but the official hash is
// authoritative only after the complete PID/creation-time/version/hash gate.
const char* currentClientBuildId() noexcept
{
    if (g_clientBuildVerified) return kExpectedClientSha256;
    if (isCanonicalSha256(g_clientSha256) &&
        _stricmp(g_clientSha256, kExpectedClientSha256) != 0) {
        return g_clientSha256;
    }
    return "UNKNOWN_UNVERIFIED";
}

const char* currentIdentityProfile() noexcept
{
    // The production binary cannot compile with kSelfTestIdentityBuild=true.
    // A test binary is labelled as a fixture only after the same complete
    // PID/creation-time/version/SHA identity gate has succeeded.
    return kSelfTestIdentityBuild && g_clientBuildVerified ?
        "TestOnlyExactFixture" : "OfficialExactClient";
}

std::uint64_t currentProcessCreationTime() noexcept
{
    FILETIME created{}, exited{}, kernel{}, user{};
    if (GetProcessTimes(GetCurrentProcess(), &created, &exited, &kernel,
                        &user) == FALSE) return 0;
    return (static_cast<std::uint64_t>(created.dwHighDateTime) << 32) |
        created.dwLowDateTime;
}

bool sha256Bytes(const unsigned char* data, DWORD bytes,
                 unsigned char digest[32]) noexcept
{
    if ((data == nullptr && bytes != 0) || digest == nullptr) return false;
    BCRYPT_ALG_HANDLE algorithm{};
    BCRYPT_HASH_HANDLE hash{};
    PUCHAR object = nullptr;
    DWORD objectBytes{};
    DWORD resultBytes{};
    bool result = false;
    if (BCryptOpenAlgorithmProvider(&algorithm, BCRYPT_SHA256_ALGORITHM,
            nullptr, 0) < 0 ||
        BCryptGetProperty(algorithm, BCRYPT_OBJECT_LENGTH,
            reinterpret_cast<PUCHAR>(&objectBytes), sizeof(objectBytes),
            &resultBytes, 0) < 0 || resultBytes != sizeof(objectBytes) ||
        objectBytes == 0) goto Cleanup;
    object = static_cast<PUCHAR>(HeapAlloc(GetProcessHeap(), 0, objectBytes));
    if (object == nullptr ||
        BCryptCreateHash(algorithm, &hash, object, objectBytes, nullptr, 0,
                         0) < 0 ||
        BCryptHashData(hash, const_cast<PUCHAR>(data), bytes, 0) < 0 ||
        BCryptFinishHash(hash, digest, 32u, 0) < 0) goto Cleanup;
    result = true;
Cleanup:
    if (hash != nullptr) BCryptDestroyHash(hash);
    if (object != nullptr) HeapFree(GetProcessHeap(), 0, object);
    if (algorithm != nullptr) BCryptCloseAlgorithmProvider(algorithm, 0);
    return result;
}

void formatSha256(const unsigned char digest[32], char output[65]) noexcept
{
    constexpr char digits[] = "0123456789ABCDEF";
    if (digest == nullptr || output == nullptr) return;
    for (DWORD index = 0; index < 32u; ++index) {
        output[index * 2u] = digits[(digest[index] >> 4) & 0x0fu];
        output[index * 2u + 1u] = digits[digest[index] & 0x0fu];
    }
    output[64] = '\0';
}

bool bridgeStateHeaderValid(const BridgeArenaV1* state,
                            std::uint64_t creationTime) noexcept
{
    if (state == nullptr) return false;
    __try {
        return state->magic == kBridgeMagic &&
            state->abiVersion == kBridgeAbiVersion &&
            state->totalBytes == kBridgeTotalBytes &&
            state->processId == GetCurrentProcessId() &&
            state->processCreationTime == creationTime &&
            state->primaryCodeVa != 0 && state->primaryStateVa != 0 &&
            state->maxRxPages == kBridgeMaxRxPages &&
            state->actualRxPages >= 0 &&
            state->actualRxPages <= static_cast<LONG>(kBridgeMaxRxPages) &&
            state->codeBytes >= 0 &&
            state->codeBytes <= static_cast<LONG>(
                kBridgeMaxRxPages * kBridgePageBytes) &&
            state->writableExecutablePageCount == 0 &&
            state->codeCanary == kBridgeCodeCanary &&
            state->stateCanary == kBridgeStateCanary;
    } __except (MemoryProbeExceptionFilter(GetExceptionCode())) {
        return false;
    }
}

bool bridgePrimaryRangesValid(const BridgeArenaV1* state) noexcept
{
    if (state == nullptr) return false;
    MEMORY_BASIC_INFORMATION codeInfo{};
    MEMORY_BASIC_INFORMATION stateInfo{};
    auto* code = reinterpret_cast<void*>(
        static_cast<std::uintptr_t>(state->primaryCodeVa));
    auto* primaryState = reinterpret_cast<void*>(
        static_cast<std::uintptr_t>(state->primaryStateVa));
    if (VirtualQuery(code, &codeInfo, sizeof(codeInfo)) == 0 ||
        VirtualQuery(primaryState, &stateInfo, sizeof(stateInfo)) == 0)
        return false;
    if (codeInfo.AllocationBase == nullptr || stateInfo.AllocationBase == nullptr ||
        codeInfo.Type != MEM_PRIVATE || stateInfo.Type != MEM_PRIVATE ||
        codeInfo.AllocationBase != code || stateInfo.AllocationBase != primaryState ||
        codeInfo.State != MEM_COMMIT || stateInfo.State != MEM_COMMIT ||
        (stateInfo.Protect & 0xffu) != PAGE_READWRITE ||
        (stateInfo.Protect & (PAGE_GUARD | PAGE_NOACCESS)) != 0)
        return false;
    const DWORD codeBytes = static_cast<DWORD>(state->codeBytes);
    if (codeBytes == 0) {
        return (codeInfo.Protect & 0xffu) == PAGE_READONLY &&
            (codeInfo.Protect & (PAGE_GUARD | PAGE_NOACCESS)) == 0;
    }
    return (codeInfo.Protect & 0xffu) == PAGE_EXECUTE_READ &&
        (codeInfo.Protect & (PAGE_GUARD | PAGE_NOACCESS)) == 0;
}

bool initializeBridgeArenaV1() noexcept
{
    if (InterlockedCompareExchange(&g_bridgeArenaInitialized, 0, 0) != 0)
        return g_bridgeState != nullptr;
    const std::uint64_t creationTime = currentProcessCreationTime();
    if (creationTime == 0) return false;
    // Find the process-lifetime MEM_PRIVATE state arena from a previous probe
    // generation. Exactly one identity-bound arena may exist. No named section
    // or writable alias is used, so a sealed code page cannot be reopened RW.
    SYSTEM_INFO systemInfo{};
    GetSystemInfo(&systemInfo);
    BridgeArenaV1* localState = nullptr;
    DWORD matches = 0;
    std::uintptr_t cursor = reinterpret_cast<std::uintptr_t>(
        systemInfo.lpMinimumApplicationAddress);
    const std::uintptr_t maximum = reinterpret_cast<std::uintptr_t>(
        systemInfo.lpMaximumApplicationAddress);
    while (cursor < maximum) {
        MEMORY_BASIC_INFORMATION info{};
        if (VirtualQuery(reinterpret_cast<void*>(cursor), &info,
                         sizeof(info)) == 0 || info.RegionSize == 0) break;
        if (info.State == MEM_COMMIT && info.Type == MEM_PRIVATE &&
            info.AllocationBase == info.BaseAddress &&
            (info.Protect & 0xffu) == PAGE_READWRITE &&
            (info.Protect & (PAGE_GUARD | PAGE_NOACCESS)) == 0 &&
            info.RegionSize == kBridgeStatePages * kBridgePageBytes) {
            auto* candidate = static_cast<BridgeArenaV1*>(info.BaseAddress);
            if (bridgeStateHeaderValid(candidate, creationTime)) {
                ++matches;
                localState = candidate;
            }
        }
        const auto next = reinterpret_cast<std::uintptr_t>(info.BaseAddress) +
            info.RegionSize;
        if (next <= cursor) break;
        cursor = next;
    }
    if (matches > 1u) {
        InterlockedIncrement(&g_bridgeArenaValidationFailures);
        return false;
    }

    unsigned char* localCode = nullptr;
    if (matches == 0u) {
        localCode = static_cast<unsigned char*>(VirtualAlloc(nullptr,
            kBridgeMaxRxPages * kBridgePageBytes, MEM_RESERVE | MEM_COMMIT,
            PAGE_READWRITE));
        if (localCode == nullptr) return false;
        localState = static_cast<BridgeArenaV1*>(VirtualAlloc(nullptr,
            kBridgeStatePages * kBridgePageBytes, MEM_RESERVE | MEM_COMMIT,
            PAGE_READWRITE));
        if (localState == nullptr) {
            VirtualFree(localCode, 0, MEM_RELEASE);
            return false;
        }
        DWORD oldProtect{};
        if (VirtualProtect(localCode, kBridgeMaxRxPages * kBridgePageBytes,
                PAGE_READONLY, &oldProtect) == FALSE) {
            VirtualFree(localCode, 0, MEM_RELEASE);
            VirtualFree(localState, 0, MEM_RELEASE);
            return false;
        }
        std::memset(localState, 0, kBridgeStatePages * kBridgePageBytes);
        localState->magic = kBridgeMagic;
        localState->abiVersion = kBridgeAbiVersion;
        localState->totalBytes = kBridgeTotalBytes;
        localState->processId = GetCurrentProcessId();
        localState->processCreationTime = creationTime;
        localState->primaryCodeVa = static_cast<std::uint32_t>(
            reinterpret_cast<std::uintptr_t>(localCode));
        localState->primaryStateVa = static_cast<std::uint32_t>(
            reinterpret_cast<std::uintptr_t>(localState));
        localState->maxRxPages = kBridgeMaxRxPages;
        localState->phase = static_cast<LONG>(BridgePhase::Detached);
        localState->captureObserverRetired = 1;
        localState->codeCanary = kBridgeCodeCanary;
        localState->stateCanary = kBridgeStateCanary;
    } else {
        InterlockedExchange(&g_bridgeArenaReused, 1);
        localCode = reinterpret_cast<unsigned char*>(
            static_cast<std::uintptr_t>(localState->primaryCodeVa));
    }
    if (!bridgePrimaryRangesValid(localState)) {
        InterlockedIncrement(&g_bridgeArenaValidationFailures);
        return false;
    }
    g_bridgePrimaryView = localState;
    g_bridgeCode = localCode;
    g_bridgeState = localState;
    InterlockedExchange(&g_bridgeArenaInitialized, 1);
    return true;
}

BridgeObserverFn acquireBridgeObserver(BridgeArenaV1* state,
                                       LONG expectedGeneration) noexcept
{
    if (state == nullptr || expectedGeneration <= 0 ||
        InterlockedCompareExchange(&state->phase, 0, 0) !=
            static_cast<LONG>(BridgePhase::Active) ||
        InterlockedCompareExchange(&state->generation, 0, 0) !=
            expectedGeneration) return nullptr;
    InterlockedIncrement(&state->observerRundown);
    MemoryBarrier();
    const LONG observer = InterlockedCompareExchange(
        &state->observerFn, 0, 0);
    if (InterlockedCompareExchange(&state->phase, 0, 0) !=
            static_cast<LONG>(BridgePhase::Active) ||
        InterlockedCompareExchange(&state->generation, 0, 0) !=
            expectedGeneration || observer == 0) {
        InterlockedDecrement(&state->observerRundown);
        return nullptr;
    }
    InterlockedIncrement(&g_bridgeObserverAcquireCount);
    return reinterpret_cast<BridgeObserverFn>(
        static_cast<std::uintptr_t>(observer));
}

void releaseBridgeObserver(BridgeArenaV1* state) noexcept
{
    if (state == nullptr) return;
    InterlockedDecrement(&state->observerRundown);
    InterlockedIncrement(&g_bridgeObserverReleaseCount);
}

bool armBridgeObserver(BridgeArenaV1* state, BridgeObserverFn observer,
                       LONG* generationOut) noexcept
{
    if (state == nullptr || observer == nullptr ||
        InterlockedCompareExchange(&state->phase,
            static_cast<LONG>(BridgePhase::Arming),
            static_cast<LONG>(BridgePhase::Detached)) !=
            static_cast<LONG>(BridgePhase::Detached) ||
        InterlockedCompareExchange(&state->observerRundown, 0, 0) != 0 ||
        InterlockedCompareExchange(&state->observerFn, 0, 0) != 0) {
        return false;
    }
    LONG generation = InterlockedIncrement(&state->generation);
    if (generation <= 0) {
        generation = 1;
        InterlockedExchange(&state->generation, generation);
    }
    InterlockedExchange(&state->captureObserverRetired, 0);
    InterlockedExchange(&state->observerFn, static_cast<LONG>(
        reinterpret_cast<std::uintptr_t>(observer)));
    MemoryBarrier();
    InterlockedExchange(&state->phase,
                        static_cast<LONG>(BridgePhase::Active));
    if (generationOut != nullptr) *generationOut = generation;
    return true;
}

bool beginBridgeObserverDisarm(BridgeArenaV1* state) noexcept
{
    if (state == nullptr) return false;
    const LONG phase = InterlockedCompareExchange(&state->phase,
        static_cast<LONG>(BridgePhase::Disarming),
        static_cast<LONG>(BridgePhase::Active));
    return phase == static_cast<LONG>(BridgePhase::Active) ||
        phase == static_cast<LONG>(BridgePhase::Disarming);
}

bool completeBridgeObserverDisarm(BridgeArenaV1* state,
                                  DWORD timeoutMs) noexcept
{
    if (state == nullptr || InterlockedCompareExchange(&state->phase, 0, 0) !=
            static_cast<LONG>(BridgePhase::Disarming)) return false;
    const ULONGLONG deadline = GetTickCount64() + timeoutMs;
    while (InterlockedCompareExchange(&state->observerRundown, 0, 0) != 0) {
        if (GetTickCount64() >= deadline) return false;
        SwitchToThread();
    }
    InterlockedExchange(&state->observerFn, 0);
    MemoryBarrier();
    InterlockedExchange(&state->captureObserverRetired, 1);
    InterlockedExchange(&state->phase,
                        static_cast<LONG>(BridgePhase::Detached));
    return true;
}

const char* bridgePhaseName(LONG phase) noexcept
{
    switch (static_cast<BridgePhase>(phase)) {
    case BridgePhase::Detached: return "Detached";
    case BridgePhase::Arming: return "Arming";
    case BridgePhase::Active: return "Active";
    case BridgePhase::Disarming: return "Disarming";
    default: return "Invalid";
    }
}

void __stdcall bridgeEpochSelfTestObserver(BridgeEventV1*) noexcept
{
    InterlockedIncrement(&g_bridgeObserverCallCount);
}

bool runBridgeEpochSelfTest() noexcept
{
    if (g_bridgeState == nullptr) return false;
    LONG generation{};
    if (!armBridgeObserver(g_bridgeState, &bridgeEpochSelfTestObserver,
                           &generation)) return false;
    BridgeEventV1 event{};
    event.size = sizeof(event);
    event.generation = static_cast<std::uint32_t>(generation);
    BridgeObserverFn observer = acquireBridgeObserver(g_bridgeState,
                                                       generation);
    if (observer == nullptr) return false;
    observer(&event);
    releaseBridgeObserver(g_bridgeState);
    const bool armed = InterlockedCompareExchange(
        &g_bridgeObserverCallCount, 0, 0) == 1;
    const bool disarmed = beginBridgeObserverDisarm(g_bridgeState) &&
        completeBridgeObserverDisarm(g_bridgeState, 1'000);
    observer = acquireBridgeObserver(g_bridgeState, generation);
    if (observer != nullptr) {
        observer(&event);
        InterlockedIncrement(&g_bridgeObserverAfterDisarmCount);
        releaseBridgeObserver(g_bridgeState);
    }
    InterlockedExchange(&g_bridgeObserverArmPassed, armed ? 1 : 0);
    InterlockedExchange(&g_bridgeObserverDisarmPassed,
        disarmed && observer == nullptr &&
        InterlockedCompareExchange(&g_bridgeState->observerRundown, 0, 0) == 0 &&
        InterlockedCompareExchange(&g_bridgeState->observerFn, 0, 0) == 0 ? 1 : 0);
    return armed && disarmed && observer == nullptr;
}

struct X86BridgeEmitter {
    unsigned char* bytes{};
    DWORD capacity{};
    DWORD used{};
    bool valid{true};

    void byte(unsigned char value) noexcept {
        if (!valid || used >= capacity) { valid = false; return; }
        bytes[used++] = value;
    }
    void word(std::uint16_t value) noexcept {
        byte(static_cast<unsigned char>(value & 0xffu));
        byte(static_cast<unsigned char>((value >> 8) & 0xffu));
    }
    void dword(std::uint32_t value) noexcept {
        for (DWORD shift = 0; shift < 32u; shift += 8u)
            byte(static_cast<unsigned char>((value >> shift) & 0xffu));
    }
    DWORD nearJump(unsigned char condition) noexcept {
        byte(0x0fu); byte(condition);
        const DWORD displacement = used;
        dword(0u);
        return displacement;
    }
    bool patchRelative32(DWORD displacementOffset, DWORD target) noexcept {
        if (!valid || displacementOffset + 4u > used ||
            target > capacity) return false;
        const std::int64_t relative = static_cast<std::int64_t>(target) -
            static_cast<std::int64_t>(displacementOffset + 4u);
        if (relative < INT32_MIN || relative > INT32_MAX) return false;
        const std::int32_t value = static_cast<std::int32_t>(relative);
        std::memcpy(bytes + displacementOffset, &value, sizeof(value));
        return true;
    }
    void absoluteLockedInc(const volatile LONG* address) noexcept {
        byte(0xf0u); byte(0xffu); byte(0x05u);
        dword(static_cast<std::uint32_t>(
            reinterpret_cast<std::uintptr_t>(address)));
    }
    void absoluteLockedDec(const volatile LONG* address) noexcept {
        byte(0xf0u); byte(0xffu); byte(0x0du);
        dword(static_cast<std::uint32_t>(
            reinterpret_cast<std::uintptr_t>(address)));
    }
};

bool emitBridgeGateway(X86BridgeEmitter& code, DWORD* gatewayOffset) noexcept
{
    if (gatewayOffset == nullptr || g_bridgeState == nullptr) return false;
    *gatewayOffset = code.used;
    // stdcall BridgeDispatch(BridgeEventV1*): acquire rundown first, then
    // recheck phase/generation/pointer before entering the DLL observer.
    code.byte(0x55u);                         // push ebp
    code.byte(0x8bu); code.byte(0xecu);       // mov ebp,esp
    code.byte(0x53u);                         // push ebx
    code.byte(0x56u);                         // push esi
    code.byte(0x8bu); code.byte(0x75u); code.byte(0x08u); // mov esi,[ebp+8]
    code.byte(0x85u); code.byte(0xf6u);       // test esi,esi
    const DWORD nullEvent = code.nearJump(0x84u);
    code.byte(0x81u); code.byte(0x3eu);       // cmp [esi],sizeof(event)
    code.dword(sizeof(BridgeEventV1));
    const DWORD badSize = code.nearJump(0x85u);
    code.byte(0xbbu);                         // mov ebx,state
    code.dword(static_cast<std::uint32_t>(
        reinterpret_cast<std::uintptr_t>(g_bridgeState)));
    code.byte(0x83u); code.byte(0x7bu);
    code.byte(static_cast<unsigned char>(offsetof(BridgeArenaV1, phase)));
    code.byte(static_cast<unsigned char>(BridgePhase::Active));
    const DWORD inactive = code.nearJump(0x85u);
    code.byte(0x8bu); code.byte(0x46u);
    code.byte(static_cast<unsigned char>(offsetof(BridgeEventV1, generation)));
    code.byte(0x3bu); code.byte(0x43u);
    code.byte(static_cast<unsigned char>(offsetof(BridgeArenaV1, generation)));
    const DWORD wrongGeneration = code.nearJump(0x85u);
    code.byte(0xf0u); code.byte(0xffu); code.byte(0x43u);
    code.byte(static_cast<unsigned char>(offsetof(BridgeArenaV1, observerRundown)));
    // A locked no-op is a full x86 barrier before the authoritative recheck.
    code.byte(0xf0u); code.byte(0x83u); code.byte(0x0cu);
    code.byte(0x24u); code.byte(0x00u);
    code.byte(0x83u); code.byte(0x7bu);
    code.byte(static_cast<unsigned char>(offsetof(BridgeArenaV1, phase)));
    code.byte(static_cast<unsigned char>(BridgePhase::Active));
    const DWORD releaseInactive = code.nearJump(0x85u);
    code.byte(0x8bu); code.byte(0x46u);
    code.byte(static_cast<unsigned char>(offsetof(BridgeEventV1, generation)));
    code.byte(0x3bu); code.byte(0x43u);
    code.byte(static_cast<unsigned char>(offsetof(BridgeArenaV1, generation)));
    const DWORD releaseGeneration = code.nearJump(0x85u);
    code.byte(0x8bu); code.byte(0x43u);
    code.byte(static_cast<unsigned char>(offsetof(BridgeArenaV1, observerFn)));
    code.byte(0x85u); code.byte(0xc0u);
    const DWORD releaseNull = code.nearJump(0x84u);
    code.byte(0x56u);                         // push esi
    code.byte(0xffu); code.byte(0xd0u);       // call eax
    const DWORD release = code.used;
    code.byte(0xf0u); code.byte(0xffu); code.byte(0x4bu);
    code.byte(static_cast<unsigned char>(offsetof(BridgeArenaV1, observerRundown)));
    const DWORD done = code.used;
    code.byte(0x5eu); code.byte(0x5bu); code.byte(0x5du);
    code.byte(0xc2u); code.word(4u);
    return code.valid &&
        code.patchRelative32(nullEvent, done) &&
        code.patchRelative32(badSize, done) &&
        code.patchRelative32(inactive, done) &&
        code.patchRelative32(wrongGeneration, done) &&
        code.patchRelative32(releaseInactive, release) &&
        code.patchRelative32(releaseGeneration, release) &&
        code.patchRelative32(releaseNull, release);
}

bool emitGenericBridgeStub(X86BridgeEmitter& code, BridgeApi api,
                           DWORD argumentCount, WORD returnBytes,
                           bool thisCall, bool captureEntryEsi,
                           DWORD gatewayOffset,
                           DWORD* entryOffset) noexcept
{
    if (g_bridgeState == nullptr || entryOffset == nullptr ||
        argumentCount > 7u) return false;
    const bool expectedThisCall = api == BridgeApi::Parser ||
        api == BridgeApi::Serializer;
    if (thisCall != expectedThisCall) return false;
    const DWORD apiIndex = static_cast<DWORD>(api);
    constexpr unsigned char savedEntryEcx = 0xf0u; // [ebp-16]
    constexpr unsigned char savedEntryLastError = 0xecu; // [ebp-20]
    constexpr unsigned char savedResult = 0xe8u; // [ebp-24]
    constexpr unsigned char savedExitLastError = 0xe4u; // [ebp-28]
    constexpr unsigned char savedGeneration = 0xe0u; // [ebp-32]
    constexpr unsigned char savedCompletionRoute = 0xdcu; // [ebp-36]
    constexpr unsigned char savedCompletionToken = 0xd8u; // [ebp-40]
    constexpr unsigned char savedCrossStage0 = 0xd4u; // [ebp-44]
    constexpr unsigned char savedCrossStage1 = 0xd0u; // [ebp-48]
    constexpr unsigned char savedPreCommitted = 0xccu; // [ebp-52]
    constexpr unsigned char savedCrossStage2 = 0xc8u; // [ebp-56]
    constexpr DWORD privateFrameBytes = 44u;
    // Preserve the original entry ESP modulo 16 across the bridge's private
    // frame, hidden frame-base word, copied arguments, and call return address.
    constexpr DWORD fixedCallFrameBytes = 16u + privateFrameBytes +
        sizeof(BridgeEventV1) + 4u + 4u;
    const DWORD stackAlignmentPad = (16u -
        ((fixedCallFrameBytes + argumentCount * 4u) & 15u)) & 15u;
    constexpr DWORD eventFromEbp = 12u + privateFrameBytes +
        sizeof(BridgeEventV1);
    const DWORD alignedEventFromEbp = eventFromEbp + stackAlignmentPad;
    *entryOffset = code.used;
    code.byte(0x55u); code.byte(0x8bu); code.byte(0xecu); // frame
    code.byte(0x53u); code.byte(0x56u); code.byte(0x57u);
    // Everything below [ebp-12] is private bridge frame state and is never
    // exposed through BridgeEventV1.  The observer may corrupt or fault after
    // partially writing every event field without gaining authority over the
    // application's ABI.
    code.byte(0x83u); code.byte(0xecu); code.byte(
        static_cast<unsigned char>(privateFrameBytes));  // sub esp,20
    code.byte(0x85u); code.byte(0x04u); code.byte(0x24u); // touch private frame
    code.byte(0x89u); code.byte(0x4du); code.byte(savedEntryEcx);
    code.byte(0xc7u); code.byte(0x45u); code.byte(savedCompletionRoute);
    code.dword(MAXDWORD);
    code.byte(0xc7u); code.byte(0x45u); code.byte(savedCompletionToken);
    code.dword(0u);
    code.byte(0xc7u); code.byte(0x45u); code.byte(savedCrossStage0);
    code.dword(0u);
    code.byte(0xc7u); code.byte(0x45u); code.byte(savedCrossStage1);
    code.dword(0u);
    code.byte(0xc7u); code.byte(0x45u); code.byte(savedPreCommitted);
    code.dword(0u);
    code.byte(0xc7u); code.byte(0x45u); code.byte(savedCrossStage2);
    code.dword(0u);
    if (stackAlignmentPad != 0u) {
        code.byte(0x83u); code.byte(0xecu);
        code.byte(static_cast<unsigned char>(stackAlignmentPad));
        code.byte(0x85u); code.byte(0x04u); code.byte(0x24u);
    }
    code.absoluteLockedInc(&g_bridgeState->bridgeFrames);
    code.absoluteLockedInc(&g_bridgeState->preOriginalRundown);
    constexpr DWORD fullProbePage = kBridgePageBytes;
    constexpr DWORD finalStackBytes = sizeof(BridgeEventV1) - fullProbePage;
    static_assert(finalStackBytes < kBridgePageBytes,
                  "Bridge stack probe must touch every crossed guard page.");
    code.byte(0x81u); code.byte(0xecu); code.dword(fullProbePage);
    code.byte(0x85u); code.byte(0x04u); code.byte(0x24u); // touch [esp]
    code.byte(0x81u); code.byte(0xecu); code.dword(finalStackBytes);
    code.byte(0x85u); code.byte(0x04u); code.byte(0x24u); // touch final page
    code.byte(0x8bu); code.byte(0xf4u);                  // mov esi,esp
    code.byte(0x33u); code.byte(0xc0u);                  // xor eax,eax
    code.byte(0x8bu); code.byte(0xfeu);                  // mov edi,esi
    code.byte(0xb9u); code.dword(static_cast<DWORD>(
        offsetof(BridgeEventV1, scratch) / sizeof(DWORD))); // header dwords
    code.byte(0xf3u); code.byte(0xabu);                  // rep stosd
    code.byte(0xc7u); code.byte(0x06u); code.dword(sizeof(BridgeEventV1));
    code.byte(0xc7u); code.byte(0x46u);
    code.byte(static_cast<unsigned char>(offsetof(BridgeEventV1, api)));
    code.dword(apiIndex);
    code.byte(0xc7u); code.byte(0x46u);
    code.byte(static_cast<unsigned char>(offsetof(BridgeEventV1, stage)));
    code.dword(static_cast<DWORD>(BridgeEventStage::BeforeOriginal));
    code.byte(0xa1u); code.dword(static_cast<std::uint32_t>(
        reinterpret_cast<std::uintptr_t>(&g_bridgeState->generation)));
    code.byte(0x89u); code.byte(0x45u); code.byte(savedGeneration);
    code.byte(0x89u); code.byte(0x46u);
    code.byte(static_cast<unsigned char>(offsetof(BridgeEventV1, generation)));
    code.byte(0x8bu); code.byte(0x45u); code.byte(0x04u);
    code.byte(0x89u); code.byte(0x46u);
    code.byte(static_cast<unsigned char>(
        offsetof(BridgeEventV1, callerReturnAddress)));
    code.byte(0x8du); code.byte(0x45u); code.byte(0x04u);
    code.byte(0x89u); code.byte(0x46u);
    code.byte(static_cast<unsigned char>(offsetof(BridgeEventV1, reserved)));
    if (captureEntryEsi) {
        code.byte(0x8bu); code.byte(0x45u); code.byte(0xf8u);
        code.byte(0x89u); code.byte(0x46u);
        code.byte(static_cast<unsigned char>(offsetof(BridgeEventV1, thisPointer)));
    } else {
        code.byte(0x8bu); code.byte(0x45u); code.byte(savedEntryEcx);
        code.byte(0x89u); code.byte(0x46u);
        code.byte(static_cast<unsigned char>(offsetof(BridgeEventV1, thisPointer)));
    }
    code.byte(0xc7u); code.byte(0x46u);
    code.byte(static_cast<unsigned char>(offsetof(BridgeEventV1, argumentCount)));
    code.dword(argumentCount);
    code.byte(0xc7u); code.byte(0x46u);
    code.byte(static_cast<unsigned char>(offsetof(BridgeEventV1, completionSlot)));
    code.dword(MAXDWORD);
    code.byte(0x64u); code.byte(0xa1u); code.dword(0x34u);
    code.byte(0x89u); code.byte(0x45u); code.byte(savedEntryLastError);
    code.byte(0x89u); code.byte(0x46u);
    code.byte(static_cast<unsigned char>(offsetof(BridgeEventV1, entryLastError)));
    for (DWORD index = 0; index < argumentCount; ++index) {
        code.byte(0x8bu); code.byte(0x45u);
        code.byte(static_cast<unsigned char>(8u + index * 4u));
        code.byte(0x89u); code.byte(0x46u);
        code.byte(static_cast<unsigned char>(
            offsetof(BridgeEventV1, arguments) + index * 4u));
    }
    if (api == BridgeApi::WSASend || api == BridgeApi::WSARecv) {
        // Reserve the application callback route in the unload-neutral bridge
        // itself, using only immutable caller-frame values.  The exact
        // per-invocation index/token stays in the private frame; no observer
        // write or identity rescan can select an older same-OVERLAPPED route.
        code.byte(0x8bu); code.byte(0x7du); code.byte(0x1cu); // edi=OVERLAPPED
        code.byte(0x85u); code.byte(0xffu);
        const DWORD noOverlapped = code.nearJump(0x84u);
        code.byte(0x83u); code.byte(0x7du); code.byte(0x20u); code.byte(0x00u);
        const DWORD noCallback = code.nearJump(0x84u);
        code.byte(0xc1u); code.byte(0xefu); code.byte(0x03u);
        code.byte(0x81u); code.byte(0xe7u);
        code.dword(kBridgeCompletionCapacity - 1u);
        const DWORD reserveLoop = code.used;
        code.byte(0x81u); code.byte(0x7du); code.byte(savedCrossStage0);
        code.dword(kBridgeCompletionCapacity);
        const DWORD capacityFull = code.nearJump(0x83u); // jae
        code.byte(0x8bu); code.byte(0xd7u);              // edx=index
        code.byte(0x6bu); code.byte(0xd2u);
        code.byte(static_cast<unsigned char>(sizeof(BridgeCompletionSlotV1)));
        code.byte(0x81u); code.byte(0xc2u);
        code.dword(static_cast<std::uint32_t>(reinterpret_cast<std::uintptr_t>(
            &g_bridgeState->completions[0])));
        code.byte(0x8bu); code.byte(0x02u);              // eax=packed token
        code.byte(0x8bu); code.byte(0xc8u);              // ecx=token
        code.byte(0x83u); code.byte(0xe1u);
        code.byte(static_cast<unsigned char>(kBridgeCompletionStateMask));
        code.byte(0x83u); code.byte(0xf9u);
        code.byte(static_cast<unsigned char>(BridgeCompletionState::Free));
        const DWORD nextBusy = code.nearJump(0x85u);
        code.byte(0x8bu); code.byte(0xc8u);
        code.byte(0x83u); code.byte(0xe1u);
        code.byte(static_cast<unsigned char>(~kBridgeCompletionStateMask));
        code.byte(0x81u); code.byte(0xf9u); code.dword(0x7ffffff8u);
        const DWORD epochExhausted = code.nearJump(0x83u);
        code.byte(0x83u); code.byte(0xc1u);
        code.byte(static_cast<unsigned char>(kBridgeCompletionTokenIncrement));
        code.byte(0x83u); code.byte(0xc9u);
        code.byte(static_cast<unsigned char>(BridgeCompletionState::Reserved));
        code.byte(0xf0u); code.byte(0x0fu); code.byte(0xb1u); code.byte(0x0au);
        const DWORD nextCasLost = code.nearJump(0x85u);
        code.byte(0x8bu); code.byte(0x42u);
        code.byte(static_cast<unsigned char>(
            offsetof(BridgeCompletionSlotV1, thunk)));
        code.byte(0x85u); code.byte(0xc0u);
        const DWORD noSealedThunk = code.nearJump(0x84u);
        code.byte(0x8bu); code.byte(0x5du); code.byte(savedGeneration);
        code.byte(0x89u); code.byte(0x5au);
        code.byte(static_cast<unsigned char>(
            offsetof(BridgeCompletionSlotV1, generation)));
        code.byte(0x8bu); code.byte(0x5du); code.byte(0x1cu);
        code.byte(0x89u); code.byte(0x5au);
        code.byte(static_cast<unsigned char>(
            offsetof(BridgeCompletionSlotV1, overlapped)));
        code.byte(0x8bu); code.byte(0x5du); code.byte(0x20u);
        code.byte(0x89u); code.byte(0x5au);
        code.byte(static_cast<unsigned char>(
            offsetof(BridgeCompletionSlotV1, applicationCompletion)));
        code.byte(0x8bu); code.byte(0xc1u);
        code.byte(0x83u); code.byte(0xe0u);
        code.byte(static_cast<unsigned char>(~kBridgeCompletionStateMask));
        code.byte(0x83u); code.byte(0xc8u);
        code.byte(static_cast<unsigned char>(BridgeCompletionState::Armed));
        code.byte(0x87u); code.byte(0x02u);              // publish Armed
        code.byte(0x89u); code.byte(0x7du); code.byte(savedCompletionRoute);
        code.byte(0x8bu); code.byte(0xc1u);
        code.byte(0x83u); code.byte(0xe0u);
        code.byte(static_cast<unsigned char>(~kBridgeCompletionStateMask));
        code.byte(0x83u); code.byte(0xc8u);
        code.byte(static_cast<unsigned char>(BridgeCompletionState::Armed));
        code.byte(0x89u); code.byte(0x45u); code.byte(savedCompletionToken);
        code.byte(0x89u); code.byte(0x7eu);
        code.byte(static_cast<unsigned char>(
            offsetof(BridgeEventV1, completionSlot)));
        code.byte(0x89u); code.byte(0x46u);
        code.byte(static_cast<unsigned char>(
            offsetof(BridgeEventV1, completionToken)));
        code.byte(0xb8u); code.dword(1u);
        code.byte(0xf0u); code.byte(0x0fu); code.byte(0xc1u); code.byte(0x05u);
        code.dword(static_cast<std::uint32_t>(reinterpret_cast<std::uintptr_t>(
            &g_bridgeState->pendingApplicationCallbacks)));
        code.byte(0x40u);                               // new pending count
        code.byte(0x8bu); code.byte(0xd8u);              // ebx=desired highwater
        const DWORD highWaterLoop = code.used;
        code.byte(0xa1u); code.dword(static_cast<std::uint32_t>(
            reinterpret_cast<std::uintptr_t>(
                &g_bridgeState->completionHighWater)));
        code.byte(0x3bu); code.byte(0xc3u);
        const DWORD highWaterDone = code.nearJump(0x8du); // jge
        code.byte(0xf0u); code.byte(0x0fu); code.byte(0xb1u); code.byte(0x1du);
        code.dword(static_cast<std::uint32_t>(reinterpret_cast<std::uintptr_t>(
            &g_bridgeState->completionHighWater)));
        const DWORD retryHighWater = code.nearJump(0x85u);
        code.byte(0xe9u);
        const DWORD reservedRoute = code.used;
        code.dword(0u);

        const DWORD rollbackNoThunk = code.used;
        code.byte(0xc7u); code.byte(0x42u);
        code.byte(static_cast<unsigned char>(
            offsetof(BridgeCompletionSlotV1, generation))); code.dword(0u);
        code.byte(0xc7u); code.byte(0x42u);
        code.byte(static_cast<unsigned char>(
            offsetof(BridgeCompletionSlotV1, overlapped))); code.dword(0u);
        code.byte(0xc7u); code.byte(0x42u);
        code.byte(static_cast<unsigned char>(
            offsetof(BridgeCompletionSlotV1, applicationCompletion)));
        code.dword(0u);
        code.byte(0x83u); code.byte(0xe1u);
        code.byte(static_cast<unsigned char>(~kBridgeCompletionStateMask));
        code.byte(0x87u); code.byte(0x0au);              // Free published last
        code.byte(0xe9u);
        const DWORD nextAfterRollback = code.used;
        code.dword(0u);

        const DWORD exhausted = code.used;
        code.absoluteLockedInc(&g_bridgeState->completionEpochExhausted);
        const DWORD reserveNext = code.used;
        code.byte(0x47u);                               // inc edi
        code.byte(0x81u); code.byte(0xe7u);
        code.dword(kBridgeCompletionCapacity - 1u);
        code.byte(0xffu); code.byte(0x45u); code.byte(savedCrossStage0);
        code.byte(0xe9u);
        const DWORD reserveAgain = code.used;
        code.dword(0u);

        const DWORD recordCapacityDrop = code.used;
        code.absoluteLockedInc(&g_bridgeState->completionCapacityDrops);
        const DWORD routeReady = code.used;
        code.byte(0xc7u); code.byte(0x45u); code.byte(savedCrossStage0);
        code.dword(0u);
        if (!code.patchRelative32(noOverlapped, routeReady) ||
            !code.patchRelative32(noCallback, routeReady) ||
            !code.patchRelative32(capacityFull, recordCapacityDrop) ||
            !code.patchRelative32(nextBusy, reserveNext) ||
            !code.patchRelative32(epochExhausted, exhausted) ||
            !code.patchRelative32(nextCasLost, reserveNext) ||
            !code.patchRelative32(noSealedThunk, rollbackNoThunk) ||
            !code.patchRelative32(highWaterDone, routeReady) ||
            !code.patchRelative32(retryHighWater, highWaterLoop) ||
            !code.patchRelative32(reservedRoute, routeReady) ||
            !code.patchRelative32(nextAfterRollback, reserveNext) ||
            !code.patchRelative32(reserveAgain, reserveLoop)) return false;
    }
    code.byte(0x56u);                                    // push event
    code.byte(0xe8u);
    const DWORD preDispatch = code.used;
    code.dword(0u);
    if (api == BridgeApi::WSASend || api == BridgeApi::WSARecv ||
        api == BridgeApi::Parser || api == BridgeApi::Serializer) {
        code.byte(0x81u); code.byte(0x7eu);
        code.byte(static_cast<unsigned char>(
            offsetof(BridgeEventV1, observerStatus)));
        code.dword(kBridgeObserverCommit);
        const DWORD observerDidNotCommit = code.nearJump(0x85u);
        code.byte(0xc7u); code.byte(0x45u); code.byte(savedPreCommitted);
        code.dword(1u);
        if (api == BridgeApi::WSASend) {
            code.byte(0x8bu); code.byte(0x46u);
            code.byte(static_cast<unsigned char>(
                offsetof(BridgeEventV1, completionSlot)));
            code.byte(0x89u); code.byte(0x45u);
            code.byte(savedCrossStage0);
            code.byte(0x8bu); code.byte(0x46u);
            code.byte(static_cast<unsigned char>(
                offsetof(BridgeEventV1, completionToken)));
            code.byte(0x89u); code.byte(0x45u);
            code.byte(savedCrossStage1);
            code.byte(0x8bu); code.byte(0x46u);
            code.byte(static_cast<unsigned char>(
                offsetof(BridgeEventV1, thisPointer)));
            code.byte(0x89u); code.byte(0x45u);
            code.byte(savedCrossStage2);
        } else if (api == BridgeApi::Parser) {
            code.byte(0x8bu); code.byte(0x46u);
            code.byte(static_cast<unsigned char>(
                offsetof(BridgeEventV1, completionSlot)));
            code.byte(0x89u); code.byte(0x45u);
            code.byte(savedCrossStage0);
        } else {
            code.byte(0x8bu); code.byte(0x46u);
            code.byte(static_cast<unsigned char>(
                offsetof(BridgeEventV1, scratchBytes)));
            code.byte(0x89u); code.byte(0x45u);
            code.byte(savedCrossStage0);
            code.byte(0x8bu); code.byte(0x46u);
            code.byte(static_cast<unsigned char>(
                offsetof(BridgeEventV1, thisPointer)));
            code.byte(0x89u); code.byte(0x45u);
            code.byte(savedCrossStage1);
        }
        DWORD committedReady{};
        DWORD noCommitNoRoute{};
        DWORD noCommitTokenChanged{};
        if (api == BridgeApi::WSASend || api == BridgeApi::WSARecv) {
            // Capture commit is authoritative for callback substitution.  If
            // the optional observer faults, is disabled, or cannot register
            // its exact pending row, retire only this invocation's packed
            // route before the original call and pass the caller's callback
            // unchanged.  A failed exact CAS leaves the route intact so the
            // application callback is still forwarded safely.
            code.byte(0xe9u);
            committedReady = code.used;
            code.dword(0u);
            const DWORD noCommit = code.used;
            code.byte(0x8bu); code.byte(0x45u);
            code.byte(savedCompletionRoute);
            code.byte(0x3du); code.dword(MAXDWORD);
            noCommitNoRoute = code.nearJump(0x84u);
            code.byte(0x6bu); code.byte(0xd0u);
            code.byte(static_cast<unsigned char>(
                sizeof(BridgeCompletionSlotV1)));
            code.byte(0x81u); code.byte(0xc2u);
            code.dword(static_cast<std::uint32_t>(
                reinterpret_cast<std::uintptr_t>(
                    &g_bridgeState->completions[0])));
            code.byte(0x8bu); code.byte(0x45u);
            code.byte(savedCompletionToken);
            code.byte(0x8bu); code.byte(0xc8u);
            code.byte(0x83u); code.byte(0xe1u);
            code.byte(static_cast<unsigned char>(
                ~kBridgeCompletionStateMask));
            code.byte(0x83u); code.byte(0xc9u);
            code.byte(static_cast<unsigned char>(
                BridgeCompletionState::Completing));
            code.byte(0xf0u); code.byte(0x0fu); code.byte(0xb1u);
            code.byte(0x0au);
            noCommitTokenChanged = code.nearJump(0x85u);
            code.byte(0xc7u); code.byte(0x42u);
            code.byte(static_cast<unsigned char>(
                offsetof(BridgeCompletionSlotV1, generation)));
            code.dword(0u);
            code.byte(0xc7u); code.byte(0x42u);
            code.byte(static_cast<unsigned char>(
                offsetof(BridgeCompletionSlotV1, overlapped)));
            code.dword(0u);
            code.byte(0xc7u); code.byte(0x42u);
            code.byte(static_cast<unsigned char>(
                offsetof(BridgeCompletionSlotV1, applicationCompletion)));
            code.dword(0u);
            code.byte(0x83u); code.byte(0xe1u);
            code.byte(static_cast<unsigned char>(
                ~kBridgeCompletionStateMask));
            code.byte(0x87u); code.byte(0x0au); // publish Free last
            code.absoluteLockedDec(
                &g_bridgeState->pendingApplicationCallbacks);
            code.byte(0xc7u); code.byte(0x45u);
            code.byte(savedCompletionRoute); code.dword(MAXDWORD);
            code.byte(0xc7u); code.byte(0x45u);
            code.byte(savedCompletionToken); code.dword(0u);
            const DWORD crossStageReady = code.used;
            if (!code.patchRelative32(observerDidNotCommit, noCommit) ||
                !code.patchRelative32(committedReady, crossStageReady) ||
                !code.patchRelative32(noCommitNoRoute, crossStageReady) ||
                !code.patchRelative32(noCommitTokenChanged,
                                      crossStageReady)) return false;
        } else {
            const DWORD crossStageReady = code.used;
            if (!code.patchRelative32(observerDidNotCommit, crossStageReady))
                return false;
        }
    }
    // Original call arguments are immutable copies from the caller frame.  In
    // particular, never reload observer-visible event.arguments here.
    code.byte(0x55u);                                    // hidden bridge EBP
    for (DWORD index = argumentCount; index != 0; --index) {
        if ((api == BridgeApi::WSASend || api == BridgeApi::WSARecv) &&
            index == 7u) {
            code.byte(0x8bu); code.byte(0x45u);
            code.byte(savedCompletionRoute);
            code.byte(0x3du); code.dword(MAXDWORD);
            const DWORD useOriginalCallback = code.nearJump(0x84u);
            code.byte(0x6bu); code.byte(0xc0u);
            code.byte(static_cast<unsigned char>(
                sizeof(BridgeCompletionSlotV1)));
            code.byte(0x05u); code.dword(static_cast<std::uint32_t>(
                reinterpret_cast<std::uintptr_t>(
                    &g_bridgeState->completions[0])));
            code.byte(0x8bu); code.byte(0x10u);
            code.byte(0x3bu); code.byte(0x55u);
            code.byte(savedCompletionToken);
            const DWORD tokenChanged = code.nearJump(0x85u);
            code.byte(0x8bu); code.byte(0x40u);
            code.byte(static_cast<unsigned char>(
                offsetof(BridgeCompletionSlotV1, thunk)));
            code.byte(0x50u);                           // push sealed thunk
            code.byte(0xe9u);
            const DWORD callbackReady = code.used;
            code.dword(0u);
            const DWORD originalCallback = code.used;
            code.byte(0xffu); code.byte(0x75u); code.byte(0x20u);
            const DWORD afterCallback = code.used;
            if (!code.patchRelative32(useOriginalCallback, originalCallback) ||
                !code.patchRelative32(tokenChanged, originalCallback) ||
                !code.patchRelative32(callbackReady, afterCallback)) return false;
        } else {
            code.byte(0xffu); code.byte(0x75u);
            code.byte(static_cast<unsigned char>(8u + (index - 1u) * 4u));
        }
    }
    // Preserve the direct-call ECX value for every ABI.  It is authoritative
    // for thiscall Parser/Serializer and harmlessly transparent for stdcall.
    code.byte(0x8bu); code.byte(0x4du); code.byte(savedEntryEcx);
    code.byte(0x8bu); code.byte(0x45u); code.byte(savedEntryLastError);
    code.byte(0x64u); code.byte(0xa3u); code.dword(0x34u);
    code.absoluteLockedDec(&g_bridgeState->preOriginalRundown);
    // The original target must observe the exact entry callee-saved registers,
    // including ESI for the confirmed Battle handler ABI.
    code.byte(0x8bu); code.byte(0x5du); code.byte(0xfcu);
    code.byte(0x8bu); code.byte(0x75u); code.byte(0xf8u);
    code.byte(0x8bu); code.byte(0x7du); code.byte(0xf4u);
    code.byte(0x8bu); code.byte(0x6du); code.byte(0x00u); // original caller EBP
    code.byte(0xffu); code.byte(0x15u);
    code.dword(static_cast<std::uint32_t>(reinterpret_cast<std::uintptr_t>(
        &g_bridgeState->apis[apiIndex].original)));
    code.byte(0x5du);                                    // recover bridge EBP
    code.byte(0x89u); code.byte(0x45u); code.byte(savedResult);
    code.byte(0x64u); code.byte(0xa1u); code.dword(0x34u); // authoritative LE
    code.byte(0x89u); code.byte(0x45u); code.byte(savedExitLastError);
    if (api == BridgeApi::WSASend || api == BridgeApi::WSARecv) {
        // A non-pending immediate failure is known not to invoke the completion
        // routine.  Retire its exact packed token in bridge code, independent of
        // DLL observer health, before any post-observation work can fault.
        code.byte(0x8bu); code.byte(0x45u); code.byte(savedCompletionRoute);
        code.byte(0x3du); code.dword(MAXDWORD);
        const DWORD noRoute = code.nearJump(0x84u);
        code.byte(0x83u); code.byte(0x7du); code.byte(savedResult);
        code.byte(0xffu);                                // cmp result,-1
        const DWORD acceptedOrImmediate = code.nearJump(0x85u);
        code.byte(0x81u); code.byte(0x7du);
        code.byte(savedExitLastError); code.dword(WSA_IO_PENDING);
        const DWORD pending = code.nearJump(0x84u);
        code.byte(0x6bu); code.byte(0xd0u);
        code.byte(static_cast<unsigned char>(sizeof(BridgeCompletionSlotV1)));
        code.byte(0x81u); code.byte(0xc2u);
        code.dword(static_cast<std::uint32_t>(reinterpret_cast<std::uintptr_t>(
            &g_bridgeState->completions[0])));
        code.byte(0x8bu); code.byte(0x45u); code.byte(savedCompletionToken);
        code.byte(0x8bu); code.byte(0xc8u);               // ecx=armed token
        code.byte(0x83u); code.byte(0xe1u);
        code.byte(static_cast<unsigned char>(~kBridgeCompletionStateMask));
        code.byte(0x83u); code.byte(0xc9u);
        code.byte(static_cast<unsigned char>(BridgeCompletionState::Completing));
        code.byte(0xf0u); code.byte(0x0fu); code.byte(0xb1u); code.byte(0x0au);
        const DWORD tokenChanged = code.nearJump(0x85u);
        code.byte(0xc7u); code.byte(0x42u);
        code.byte(static_cast<unsigned char>(
            offsetof(BridgeCompletionSlotV1, generation)));
        code.dword(0u);
        code.byte(0xc7u); code.byte(0x42u);
        code.byte(static_cast<unsigned char>(
            offsetof(BridgeCompletionSlotV1, overlapped)));
        code.dword(0u);
        code.byte(0xc7u); code.byte(0x42u);
        code.byte(static_cast<unsigned char>(
            offsetof(BridgeCompletionSlotV1, applicationCompletion)));
        code.dword(0u);
        code.byte(0x83u); code.byte(0xe1u);
        code.byte(static_cast<unsigned char>(~kBridgeCompletionStateMask));
        code.byte(0x87u); code.byte(0x0au);               // publish Free last
        code.absoluteLockedDec(&g_bridgeState->pendingApplicationCallbacks);
        const DWORD routeRetired = code.used;
        if (!code.patchRelative32(noRoute, routeRetired) ||
            !code.patchRelative32(acceptedOrImmediate, routeRetired) ||
            !code.patchRelative32(pending, routeRetired) ||
            !code.patchRelative32(tokenChanged, routeRetired)) return false;
    }
    // Recompute the event address after the original returns; ESI was restored
    // for the application and must not be assumed to retain the event pointer.
    code.byte(0x8du); code.byte(0xb5u);
    code.dword(static_cast<std::uint32_t>(
        -static_cast<std::int32_t>(alignedEventFromEbp)));
    // Reconstitute every authoritative header/ABI field from the caller or
    // private frame before the post observer.  Pre-observer corruption cannot
    // persist into cleanup or completion-route decisions.
    code.byte(0xc7u); code.byte(0x06u); code.dword(sizeof(BridgeEventV1));
    code.byte(0xc7u); code.byte(0x46u);
    code.byte(static_cast<unsigned char>(offsetof(BridgeEventV1, api)));
    code.dword(apiIndex);
    code.byte(0x8bu); code.byte(0x45u); code.byte(savedGeneration);
    code.byte(0x89u); code.byte(0x46u);
    code.byte(static_cast<unsigned char>(offsetof(BridgeEventV1, generation)));
    code.byte(0x8bu); code.byte(0x45u); code.byte(0x04u);
    code.byte(0x89u); code.byte(0x46u);
    code.byte(static_cast<unsigned char>(
        offsetof(BridgeEventV1, callerReturnAddress)));
    code.byte(0x8du); code.byte(0x45u); code.byte(0x04u);
    code.byte(0x89u); code.byte(0x46u);
    code.byte(static_cast<unsigned char>(offsetof(BridgeEventV1, reserved)));
    if (api == BridgeApi::WSARecv) {
        code.byte(0x8bu); code.byte(0x45u); code.byte(savedCrossStage1);
    } else if (api == BridgeApi::WSASend) {
        code.byte(0x8bu); code.byte(0x45u); code.byte(savedCrossStage2);
    } else if (captureEntryEsi) {
        code.byte(0x8bu); code.byte(0x45u); code.byte(0xf8u);
    } else {
        code.byte(0x8bu); code.byte(0x45u); code.byte(savedEntryEcx);
    }
    code.byte(0x89u); code.byte(0x46u);
    code.byte(static_cast<unsigned char>(offsetof(BridgeEventV1, thisPointer)));
    code.byte(0xc7u); code.byte(0x46u);
    code.byte(static_cast<unsigned char>(offsetof(BridgeEventV1, argumentCount)));
    code.dword(argumentCount);
    for (DWORD index = 0; index < argumentCount; ++index) {
        code.byte(0x8bu); code.byte(0x45u);
        code.byte(static_cast<unsigned char>(8u + index * 4u));
        code.byte(0x89u); code.byte(0x46u);
        code.byte(static_cast<unsigned char>(
            offsetof(BridgeEventV1, arguments) + index * 4u));
    }
    if (api == BridgeApi::WSARecv) {
        code.byte(0x8bu); code.byte(0x45u); code.byte(savedCompletionRoute);
        code.byte(0x89u); code.byte(0x46u);
        code.byte(static_cast<unsigned char>(
            offsetof(BridgeEventV1, completionSlot)));
        code.byte(0x8bu); code.byte(0x45u); code.byte(savedCompletionToken);
        code.byte(0x89u); code.byte(0x46u);
        code.byte(static_cast<unsigned char>(
            offsetof(BridgeEventV1, completionToken)));
        code.byte(0x8bu); code.byte(0x45u); code.byte(savedCrossStage0);
        code.byte(0x89u); code.byte(0x46u);
        code.byte(static_cast<unsigned char>(
            offsetof(BridgeEventV1, scratchBytes)));
    } else if (api == BridgeApi::WSASend) {
        code.byte(0x8bu); code.byte(0x45u); code.byte(savedCrossStage0);
        code.byte(0x89u); code.byte(0x46u);
        code.byte(static_cast<unsigned char>(
            offsetof(BridgeEventV1, completionSlot)));
        code.byte(0x8bu); code.byte(0x45u); code.byte(savedCrossStage1);
        code.byte(0x89u); code.byte(0x46u);
        code.byte(static_cast<unsigned char>(
            offsetof(BridgeEventV1, completionToken)));
    } else if (api == BridgeApi::Parser) {
        code.byte(0x8bu); code.byte(0x45u); code.byte(savedCrossStage0);
        code.byte(0x89u); code.byte(0x46u);
        code.byte(static_cast<unsigned char>(
            offsetof(BridgeEventV1, completionSlot)));
        code.byte(0xc7u); code.byte(0x46u);
        code.byte(static_cast<unsigned char>(
            offsetof(BridgeEventV1, completionToken)));
        code.dword(0u);
    } else {
        code.byte(0xc7u); code.byte(0x46u);
        code.byte(static_cast<unsigned char>(
            offsetof(BridgeEventV1, completionSlot)));
        code.dword(MAXDWORD);
        code.byte(0xc7u); code.byte(0x46u);
        code.byte(static_cast<unsigned char>(
            offsetof(BridgeEventV1, completionToken)));
        code.dword(0u);
    }
    code.byte(0xc7u); code.byte(0x46u);
    code.byte(static_cast<unsigned char>(offsetof(BridgeEventV1, observerStatus)));
    code.dword(0u);
    code.byte(0x8bu); code.byte(0x45u); code.byte(savedEntryLastError);
    code.byte(0x89u); code.byte(0x46u);
    code.byte(static_cast<unsigned char>(offsetof(BridgeEventV1, entryLastError)));
    code.byte(0x8bu); code.byte(0x45u); code.byte(savedResult);
    code.byte(0x89u); code.byte(0x46u);
    code.byte(static_cast<unsigned char>(offsetof(BridgeEventV1, result)));
    code.byte(0x8bu); code.byte(0x45u); code.byte(savedExitLastError);
    code.byte(0x89u); code.byte(0x46u);
    code.byte(static_cast<unsigned char>(offsetof(BridgeEventV1, lastError)));
    code.byte(0xc7u); code.byte(0x46u);
    code.byte(static_cast<unsigned char>(offsetof(BridgeEventV1, stage)));
    code.dword(static_cast<DWORD>(BridgeEventStage::AfterOriginal));
    DWORD postNotCommitted{};
    if (api == BridgeApi::WSASend || api == BridgeApi::WSARecv ||
        api == BridgeApi::Parser || api == BridgeApi::Serializer) {
        code.byte(0x83u); code.byte(0x7du); code.byte(savedPreCommitted);
        code.byte(0x00u);
        postNotCommitted = code.nearJump(0x84u);
    }
    code.byte(0x56u);
    code.byte(0xe8u);
    const DWORD postDispatch = code.used;
    code.dword(0u);
    const DWORD postComplete = code.used;
    if (postNotCommitted != 0u &&
        !code.patchRelative32(postNotCommitted, postComplete)) return false;
    code.byte(0x8bu); code.byte(0x45u); code.byte(savedExitLastError);
    code.byte(0x64u); code.byte(0xa3u); code.dword(0x34u);
    code.byte(0x8bu); code.byte(0x45u); code.byte(savedResult);
    code.absoluteLockedDec(&g_bridgeState->bridgeFrames);
    code.byte(0x8du); code.byte(0x65u); code.byte(0xf4u);
    code.byte(0x5fu); code.byte(0x5eu); code.byte(0x5bu); code.byte(0x5du);
    code.byte(0xc2u); code.word(returnBytes);
    return code.valid && code.patchRelative32(preDispatch, gatewayOffset) &&
        code.patchRelative32(postDispatch, gatewayOffset);
}

bool emitBridgeCompletionThunks(X86BridgeEmitter& code, DWORD gatewayOffset,
                                 DWORD* commonOffset,
                                 std::uintptr_t privateAbaBarrierAddress) noexcept
{
    if (commonOffset == nullptr || g_bridgeState == nullptr) return false;
    *commonOffset = code.used;
    code.byte(0x55u); code.byte(0x8bu); code.byte(0xecu);
    code.byte(0x53u); code.byte(0x56u); code.byte(0x57u);
    constexpr DWORD privateFrameBytes = 16u;
    constexpr unsigned char savedEntryLastError = 0xf0u; // [ebp-16]
    constexpr unsigned char savedApplicationCallback = 0xecu; // [ebp-20]
    constexpr unsigned char savedOverlapped = 0xe8u; // [ebp-24]
    constexpr unsigned char savedPackedToken = 0xe4u; // [ebp-28]
    code.byte(0x83u); code.byte(0xecu); code.byte(
        static_cast<unsigned char>(privateFrameBytes));
    code.byte(0x85u); code.byte(0x04u); code.byte(0x24u);
    code.absoluteLockedInc(&g_bridgeState->bridgeFrames);
    constexpr DWORD finalStackBytes = sizeof(BridgeEventV1) - kBridgePageBytes;
    code.byte(0x81u); code.byte(0xecu); code.dword(kBridgePageBytes);
    code.byte(0x85u); code.byte(0x04u); code.byte(0x24u);
    code.byte(0x81u); code.byte(0xecu); code.dword(finalStackBytes);
    code.byte(0x85u); code.byte(0x04u); code.byte(0x24u);
    code.byte(0x8bu); code.byte(0xf4u);                  // event
    code.byte(0x33u); code.byte(0xc0u);
    code.byte(0x8bu); code.byte(0xfeu);
    code.byte(0xb9u); code.dword(static_cast<DWORD>(
        offsetof(BridgeEventV1, scratch) / sizeof(DWORD)));
    code.byte(0xf3u); code.byte(0xabu);
    code.byte(0xc7u); code.byte(0x06u); code.dword(sizeof(BridgeEventV1));
    code.byte(0x64u); code.byte(0xa1u); code.dword(0x34u);
    code.byte(0x89u); code.byte(0x45u); code.byte(savedEntryLastError);
    code.byte(0x89u); code.byte(0x46u);
    code.byte(static_cast<unsigned char>(
        offsetof(BridgeEventV1, entryLastError)));
    code.byte(0x8bu); code.byte(0x45u); code.byte(0x04u); // slot index
    code.byte(0x3du); code.dword(kBridgeCompletionCapacity);
    const DWORD invalidIndex = code.nearJump(0x83u);     // jae
    code.byte(0x6bu); code.byte(0xd8u);
    code.byte(static_cast<unsigned char>(sizeof(BridgeCompletionSlotV1)));
    code.byte(0x81u); code.byte(0xc3u);
    code.dword(static_cast<std::uint32_t>(reinterpret_cast<std::uintptr_t>(
        &g_bridgeState->completions[0])));
    // Snapshot the full packed epoch+phase before checking identity.  The final
    // cmpxchg uses this exact token so a paused old callback cannot ABA-claim a
    // route that was freed and re-armed in the meantime.
    code.byte(0x8bu); code.byte(0x03u);                   // eax=packed token
    code.byte(0x89u); code.byte(0x45u); code.byte(savedPackedToken);
    code.byte(0x8bu); code.byte(0xd0u);                   // edx=eax
    code.byte(0x83u); code.byte(0xe2u);
    code.byte(static_cast<unsigned char>(kBridgeCompletionStateMask));
    code.byte(0x83u); code.byte(0xfau);
    code.byte(static_cast<unsigned char>(BridgeCompletionState::Armed));
    const DWORD notArmed = code.nearJump(0x85u);
    // Reject a stale thunk before claiming the slot.  A mismatched callback
    // must not consume or redirect a newer Armed route.
    code.byte(0x8bu); code.byte(0x4bu);
    code.byte(static_cast<unsigned char>(
        offsetof(BridgeCompletionSlotV1, overlapped)));
    code.byte(0x3bu); code.byte(0x4du); code.byte(0x14u);
    const DWORD staleIdentity = code.nearJump(0x85u);
    if (privateAbaBarrierAddress != 0u) {
        // Private-machine-fixture-only pause after the authoritative token and
        // identity snapshot but before the exact-token CAS.  Production bridge
        // bytes omit this entire block and never reference a DLL address.
        code.byte(0xb8u); code.dword(1u);                // eax=ArmedForPause
        code.byte(0xb9u); code.dword(2u);                // ecx=Paused
        code.byte(0xf0u); code.byte(0x0fu); code.byte(0xb1u);
        code.byte(0x0du); code.dword(static_cast<std::uint32_t>(
            privateAbaBarrierAddress));
        const DWORD notFirstBarrierThread = code.nearJump(0x85u);
        code.byte(0xb9u); code.dword(20'000'000u);       // bounded spin
        const DWORD barrierSpin = code.used;
        code.byte(0x83u); code.byte(0x3du);
        code.dword(static_cast<std::uint32_t>(privateAbaBarrierAddress));
        code.byte(0x03u);                               // cmp state,Released
        const DWORD barrierReleased = code.nearJump(0x84u);
        code.byte(0xf3u); code.byte(0x90u);              // pause
        code.byte(0x49u);                               // dec ecx
        code.byte(0x0fu); code.byte(0x85u);
        const DWORD spinDisplacement = code.used;
        code.dword(0u);
        code.byte(0xc7u); code.byte(0x05u);
        code.dword(static_cast<std::uint32_t>(privateAbaBarrierAddress));
        code.dword(4u);                                 // bounded timeout
        const DWORD afterBarrier = code.used;
        if (!code.patchRelative32(notFirstBarrierThread, afterBarrier) ||
            !code.patchRelative32(barrierReleased, afterBarrier) ||
            !code.patchRelative32(spinDisplacement, barrierSpin)) return false;
    }
    code.byte(0x8bu); code.byte(0x45u); code.byte(savedPackedToken);
    code.byte(0x8bu); code.byte(0xd0u);
    code.byte(0x83u); code.byte(0xe2u);
    code.byte(static_cast<unsigned char>(~kBridgeCompletionStateMask));
    code.byte(0x83u); code.byte(0xcau);
    code.byte(static_cast<unsigned char>(BridgeCompletionState::Completing));
    code.byte(0xf0u); code.byte(0x0fu); code.byte(0xb1u); code.byte(0x13u);
    const DWORD duplicate = code.nearJump(0x85u);
    code.byte(0x8bu); code.byte(0x7bu);
    code.byte(static_cast<unsigned char>(
        offsetof(BridgeCompletionSlotV1, applicationCompletion)));
    code.byte(0x89u); code.byte(0x7du);
    code.byte(savedApplicationCallback);
    code.byte(0x8bu); code.byte(0x43u);
    code.byte(static_cast<unsigned char>(
        offsetof(BridgeCompletionSlotV1, overlapped)));
    code.byte(0x89u); code.byte(0x45u); code.byte(savedOverlapped);
    code.byte(0x85u); code.byte(0xffu);
    const DWORD nullCallback = code.nearJump(0x84u);
    code.byte(0xc7u); code.byte(0x46u);
    code.byte(static_cast<unsigned char>(offsetof(BridgeEventV1, api)));
    code.dword(static_cast<DWORD>(BridgeApi::WSARecvCompletionRoutine));
    code.byte(0xc7u); code.byte(0x46u);
    code.byte(static_cast<unsigned char>(offsetof(BridgeEventV1, stage)));
    code.dword(static_cast<DWORD>(BridgeEventStage::Completion));
    code.byte(0x8bu); code.byte(0x43u);
    code.byte(static_cast<unsigned char>(
        offsetof(BridgeCompletionSlotV1, generation)));
    code.byte(0x89u); code.byte(0x46u);
    code.byte(static_cast<unsigned char>(offsetof(BridgeEventV1, generation)));
    code.byte(0x8bu); code.byte(0x45u); code.byte(0x04u);
    code.byte(0x89u); code.byte(0x46u);
    code.byte(static_cast<unsigned char>(offsetof(BridgeEventV1, completionSlot)));
    code.byte(0x8bu); code.byte(0x45u); code.byte(savedPackedToken);
    code.byte(0x89u); code.byte(0x46u);
    code.byte(static_cast<unsigned char>(offsetof(BridgeEventV1, completionToken)));
    code.byte(0x89u); code.byte(0x7eu);
    code.byte(static_cast<unsigned char>(offsetof(BridgeEventV1, reserved)));
    code.byte(0xc7u); code.byte(0x46u);
    code.byte(static_cast<unsigned char>(offsetof(BridgeEventV1, argumentCount)));
    code.dword(4u);
    for (DWORD index = 0; index < 4u; ++index) {
        code.byte(0x8bu); code.byte(0x45u);
        code.byte(static_cast<unsigned char>(12u + index * 4u));
        code.byte(0x89u); code.byte(0x46u);
        code.byte(static_cast<unsigned char>(
            offsetof(BridgeEventV1, arguments) + index * 4u));
    }
    // Retire the routing identity before observer/app callback. This permits a
    // callback to repost the same OVERLAPPED without losing exactly-once flow.
    code.byte(0xc7u); code.byte(0x43u);
    code.byte(static_cast<unsigned char>(
        offsetof(BridgeCompletionSlotV1, overlapped)));
    code.dword(0u);
    code.byte(0xc7u); code.byte(0x43u);
    code.byte(static_cast<unsigned char>(
        offsetof(BridgeCompletionSlotV1, applicationCompletion)));
    code.dword(0u);
    code.byte(0xc7u); code.byte(0x43u);
    code.byte(static_cast<unsigned char>(
        offsetof(BridgeCompletionSlotV1, generation)));
    code.dword(0u);
    code.byte(0x8bu); code.byte(0x55u); code.byte(savedPackedToken);
    code.byte(0x83u); code.byte(0xe2u);
    code.byte(static_cast<unsigned char>(~kBridgeCompletionStateMask));
    code.byte(0x87u); code.byte(0x13u);                  // xchg [ebx],edx
    code.absoluteLockedDec(&g_bridgeState->pendingApplicationCallbacks);
    code.byte(0x56u); code.byte(0xe8u);
    const DWORD dispatch = code.used;
    code.dword(0u);
    code.byte(0x8bu); code.byte(0x45u); code.byte(savedEntryLastError);
    code.byte(0x64u); code.byte(0xa3u); code.dword(0x34u);
    code.byte(0x8bu); code.byte(0x45u);
    code.byte(savedApplicationCallback);
    code.absoluteLockedDec(&g_bridgeState->bridgeFrames);
    code.byte(0x8du); code.byte(0x65u); code.byte(0xf4u);
    code.byte(0x5fu); code.byte(0x5eu); code.byte(0x5bu); code.byte(0x5du);
    code.byte(0x83u); code.byte(0xc4u); code.byte(0x04u); // remove index
    code.byte(0xffu); code.byte(0xe0u);                  // tail jmp callback
    const DWORD mismatch = code.used;
    code.absoluteLockedInc(&g_bridgeState->completionIdentityMismatches);
    code.byte(0xe9u);
    const DWORD mismatchJoin = code.used;
    code.dword(0u);
    const DWORD releaseNullSlot = code.used;
    code.byte(0xc7u); code.byte(0x43u);
    code.byte(static_cast<unsigned char>(
        offsetof(BridgeCompletionSlotV1, overlapped)));
    code.dword(0u);
    code.byte(0xc7u); code.byte(0x43u);
    code.byte(static_cast<unsigned char>(
        offsetof(BridgeCompletionSlotV1, applicationCompletion)));
    code.dword(0u);
    code.byte(0xc7u); code.byte(0x43u);
    code.byte(static_cast<unsigned char>(
        offsetof(BridgeCompletionSlotV1, generation)));
    code.dword(0u);
    code.byte(0x8bu); code.byte(0x45u); code.byte(savedPackedToken);
    code.byte(0x83u); code.byte(0xe0u);
    code.byte(static_cast<unsigned char>(~kBridgeCompletionStateMask));
    code.byte(0x87u); code.byte(0x03u);                  // xchg [ebx],eax
    code.absoluteLockedDec(&g_bridgeState->pendingApplicationCallbacks);
    const DWORD invalid = code.used;
    code.absoluteLockedDec(&g_bridgeState->bridgeFrames);
    code.byte(0x8du); code.byte(0x65u); code.byte(0xf4u);
    code.byte(0x5fu); code.byte(0x5eu); code.byte(0x5bu); code.byte(0x5du);
    code.byte(0x83u); code.byte(0xc4u); code.byte(0x04u);
    code.byte(0xc2u); code.word(16u);
    if (!code.valid || !code.patchRelative32(invalidIndex, invalid) ||
        !code.patchRelative32(notArmed, invalid) ||
        !code.patchRelative32(staleIdentity, mismatch) ||
        !code.patchRelative32(duplicate, invalid) ||
        !code.patchRelative32(nullCallback, releaseNullSlot) ||
        !code.patchRelative32(mismatchJoin, invalid) ||
        !code.patchRelative32(dispatch, gatewayOffset)) return false;

    std::memset(g_bridgeCompletionThunkOffsets, 0,
                sizeof(g_bridgeCompletionThunkOffsets));
    for (DWORD index = 0; index < kBridgeCompletionCapacity; ++index) {
        g_bridgeCompletionThunkOffsets[index] = code.used;
        code.byte(0x68u); code.dword(index);
        code.byte(0xe9u);
        const DWORD jump = code.used;
        code.dword(0u);
        if (!code.patchRelative32(jump, *commonOffset)) return false;
    }
    return code.valid;
}

bool emitBridgeOutboundPersistentGateway(X86BridgeEmitter& code,
                                         DWORD* offset) noexcept
{
    if (offset == nullptr) return false;
    auto* const base = reinterpret_cast<unsigned char*>(
        GetModuleHandleW(nullptr));
    if (base == nullptr) return false;
    constexpr DWORD kOutboundEnqueueRva = 0x0007FC10u;
    *offset = code.used;
    // Exact verified prologue followed by an absolute tail transfer.  PUSH/RET
    // keeps the original caller return address below the function prologue and
    // avoids a staging-address-dependent rel32 in the sealed template.
    code.byte(0x55u); code.byte(0x8Bu); code.byte(0xECu);
    code.byte(0x56u); code.byte(0x57u);
    code.byte(0x68u);
    code.dword(static_cast<DWORD>(reinterpret_cast<std::uintptr_t>(
        base + kOutboundEnqueueRva + 5u)));
    code.byte(0xC3u);
    return code.valid;
}

bool buildBridgeCodeTemplate(unsigned char* destination, DWORD capacity,
                             DWORD* bytesOut,
                             std::uintptr_t privateAbaBarrierAddress = 0u) noexcept
{
    if (destination == nullptr || bytesOut == nullptr ||
        capacity < kBridgePageBytes || g_bridgeState == nullptr) return false;
    std::memset(destination, 0xcc, capacity);
    X86BridgeEmitter code{destination, capacity, 0u, true};
    code.dword(kBridgeCodeCanary);
    code.dword(kBridgeAbiVersion);
    code.dword(0u); // patched with final bytes
    code.dword(kBridgeStateCanary);
    if (!emitBridgeGateway(code, &g_bridgeGatewayOffset)) return false;
    std::memset(g_bridgeEntryOffsets, 0, sizeof(g_bridgeEntryOffsets));
    // Completion thunks are emitted first so the WSARecv gateway can embed and
    // validate the exact sealed thunk address selected by the observer request.
    if (!emitBridgeCompletionThunks(code, g_bridgeGatewayOffset,
             &g_bridgeEntryOffsets[static_cast<DWORD>(
                 BridgeApi::WSARecvCompletionRoutine)],
            privateAbaBarrierAddress)) return false;
    const struct Spec {
        BridgeApi api; DWORD args; WORD pop; bool thisCall; bool captureEsi;
    } specs[] = {
        {BridgeApi::Send, 4u, 16u, false, false},
        {BridgeApi::WSASend, 7u, 28u, false, false},
        {BridgeApi::Recv, 4u, 16u, false, false},
        {BridgeApi::WSARecv, 7u, 28u, false, false},
        {BridgeApi::WSAGetOverlappedResult, 5u, 20u, false, false},
        {BridgeApi::GetQueuedCompletionStatus, 5u, 20u, false, false},
        {BridgeApi::GetQueuedCompletionStatusEx, 6u, 24u, false, false},
        {BridgeApi::Parser, 2u, 8u, true, false},
        {BridgeApi::Serializer, 3u, 12u, true, false},
        {BridgeApi::Handler, 1u, 4u, false, true}
    };
    for (const auto& spec : specs) {
        if (!emitGenericBridgeStub(code, spec.api, spec.args, spec.pop,
                spec.thisCall, spec.captureEsi, g_bridgeGatewayOffset,
                &g_bridgeEntryOffsets[static_cast<DWORD>(spec.api)]))
            return false;
    }
    if (!emitBridgeOutboundPersistentGateway(
            code, &g_bridgeOutboundGatewayOffset)) return false;
    if (!code.valid || code.used == 0 || code.used > capacity) return false;
    std::memcpy(destination + 8u, &code.used, sizeof(code.used));
    *bytesOut = code.used;
    return true;
}

bool verifyBridgeCodeProtection(const unsigned char* code, DWORD codeBytes,
                                DWORD actualPages) noexcept
{
    if (code == nullptr || codeBytes == 0 || actualPages == 0 ||
        actualPages > kBridgeMaxRxPages ||
        codeBytes > actualPages * kBridgePageBytes) return false;
    for (DWORD page = 0; page < kBridgeMaxRxPages; ++page) {
        MEMORY_BASIC_INFORMATION info{};
        const auto* address = code + page * kBridgePageBytes;
        if (VirtualQuery(address, &info, sizeof(info)) == 0 ||
            info.Type != MEM_PRIVATE || info.State != MEM_COMMIT ||
            info.AllocationBase != code ||
            (info.Protect & (PAGE_GUARD | PAGE_NOACCESS)) != 0) return false;
        const DWORD expected = page < actualPages ? PAGE_EXECUTE_READ :
            PAGE_READONLY;
        if ((info.Protect & 0xffu) != expected) return false;
    }
    return true;
}

bool ensureBridgeCodeV1() noexcept
{
    if (g_bridgeState == nullptr || g_bridgeCode == nullptr ||
        InterlockedCompareExchange(&g_bridgeState->phase, 0, 0) !=
            static_cast<LONG>(BridgePhase::Detached) ||
        InterlockedCompareExchange(&g_bridgeState->observerRundown, 0, 0) != 0 ||
        InterlockedCompareExchange(&g_bridgeState->preOriginalRundown, 0, 0) != 0)
        return false;
    auto* expected = static_cast<unsigned char*>(HeapAlloc(GetProcessHeap(), 0,
        kBridgeMaxRxPages * kBridgePageBytes));
    if (expected == nullptr) return false;
    DWORD expectedBytes{};
    unsigned char expectedDigest[32]{};
    bool ok = buildBridgeCodeTemplate(expected,
        kBridgeMaxRxPages * kBridgePageBytes, &expectedBytes) &&
        sha256Bytes(expected, expectedBytes, expectedDigest);
    const LONG existingBytes = InterlockedCompareExchange(
        &g_bridgeState->codeBytes, 0, 0);
    bool constructionWritable = false;
    if (ok && existingBytes == 0) {
        DWORD oldProtect{};
        ok = VirtualProtect(g_bridgeCode,
            kBridgeMaxRxPages * kBridgePageBytes, PAGE_READWRITE,
            &oldProtect) != FALSE;
        constructionWritable = ok;
        if (ok) {
            std::memcpy(g_bridgeCode, expected,
                        kBridgeMaxRxPages * kBridgePageBytes);
            ok = FlushInstructionCache(GetCurrentProcess(), g_bridgeCode,
                                       expectedBytes) != FALSE;
            const DWORD actualPages = (expectedBytes + kBridgePageBytes - 1u) /
                kBridgePageBytes;
            DWORD ignored{};
            ok = ok && VirtualProtect(g_bridgeCode,
                    actualPages * kBridgePageBytes,
                    PAGE_EXECUTE_READ, &ignored) != FALSE;
            if (ok && actualPages < kBridgeMaxRxPages) {
                ok = VirtualProtect(g_bridgeCode + actualPages * kBridgePageBytes,
                    (kBridgeMaxRxPages - actualPages) * kBridgePageBytes,
                    PAGE_READONLY, &ignored) != FALSE;
            }
            if (ok) {
                std::memcpy(g_bridgeState->codeSha256, expectedDigest,
                            sizeof(expectedDigest));
                InterlockedExchange(&g_bridgeState->actualRxPages,
                                    static_cast<LONG>(actualPages));
                InterlockedExchange(&g_bridgeState->codeBytes,
                                    static_cast<LONG>(expectedBytes));
                constructionWritable = false;
            }
        }
    } else if (ok && existingBytes == static_cast<LONG>(expectedBytes)) {
        unsigned char liveDigest[32]{};
        ok = std::memcmp(g_bridgeCode, expected, expectedBytes) == 0 &&
            sha256Bytes(g_bridgeCode, expectedBytes, liveDigest) &&
            std::memcmp(liveDigest, expectedDigest, sizeof(liveDigest)) == 0 &&
            std::memcmp(liveDigest, g_bridgeState->codeSha256,
                        sizeof(liveDigest)) == 0;
    } else {
        ok = false;
    }
    if (!ok && constructionWritable) {
        DWORD ignored{};
        VirtualProtect(g_bridgeCode,
            kBridgeMaxRxPages * kBridgePageBytes, PAGE_READONLY, &ignored);
        FlushInstructionCache(GetCurrentProcess(), g_bridgeCode,
                              kBridgeMaxRxPages * kBridgePageBytes);
        std::memset(g_bridgeState->codeSha256, 0,
                    sizeof(g_bridgeState->codeSha256));
        InterlockedExchange(&g_bridgeState->actualRxPages, 0);
        InterlockedExchange(&g_bridgeState->codeBytes, 0);
        for (DWORD index = 0; index < kBridgeMaximumApis; ++index)
            InterlockedExchange(&g_bridgeState->apis[index].entry, 0);
    }
    const DWORD actualPages = static_cast<DWORD>(InterlockedCompareExchange(
        &g_bridgeState->actualRxPages, 0, 0));
    ok = ok && verifyBridgeCodeProtection(g_bridgeCode, expectedBytes,
                                           actualPages);
    if (ok) {
        formatSha256(expectedDigest, g_bridgeCodeSha256);
        for (DWORD index = 0; index < kBridgeMaximumApis; ++index) {
            InterlockedExchange(&g_bridgeState->apis[index].entry,
                g_bridgeEntryOffsets[index] == 0 ? 0 : static_cast<LONG>(
                    reinterpret_cast<std::uintptr_t>(g_bridgeCode +
                        g_bridgeEntryOffsets[index])));
        }
        for (DWORD index = 0; index < kBridgeCompletionCapacity; ++index) {
            const LONG expectedThunk = static_cast<LONG>(
                reinterpret_cast<std::uintptr_t>(g_bridgeCode +
                    g_bridgeCompletionThunkOffsets[index]));
            const LONG state = InterlockedCompareExchange(
                &g_bridgeState->completions[index].state, 0, 0);
            const LONG existingThunk = InterlockedCompareExchange(
                &g_bridgeState->completions[index].thunk, 0, 0);
            if (state != static_cast<LONG>(BridgeCompletionState::Free) &&
                existingThunk != expectedThunk) {
                ok = false;
                break;
            }
            if (existingThunk == 0)
                InterlockedExchange(
                    &g_bridgeState->completions[index].thunk, expectedThunk);
            else if (existingThunk != expectedThunk) {
                ok = false;
                break;
            }
        }
    }
    if (!ok) InterlockedIncrement(&g_bridgeArenaValidationFailures);
    HeapFree(GetProcessHeap(), 0, expected);
    return ok;
}

