class DeepHookActivity final {
public:
    DeepHookActivity() noexcept {
        ++g_hookThreadContextDepth;
        InterlockedIncrement(&g_activeHooks);
    }
    ~DeepHookActivity() {
        InterlockedDecrement(&g_activeHooks);
        --g_hookThreadContextDepth;
    }
    DeepHookActivity(const DeepHookActivity&) = delete;
    DeepHookActivity& operator=(const DeepHookActivity&) = delete;
};

bool isHookThreadContext() noexcept
{
    return g_inHook || g_hookThreadContextDepth > 0;
}

struct PatchHazardRange {
    std::uintptr_t begin{};
    std::uintptr_t end{};
};

struct PatchThreadTransaction {
    HANDLE handles[512]{};
    DWORD ids[512]{};
    DWORD count{};
};

void resumePatchThreadTransaction(PatchThreadTransaction* transaction) noexcept
{
    if (transaction == nullptr) return;
    while (transaction->count != 0) {
        const DWORD index = --transaction->count;
        ResumeThread(transaction->handles[index]);
        CloseHandle(transaction->handles[index]);
        transaction->handles[index] = nullptr;
        transaction->ids[index] = 0;
    }
}

bool patchInstructionPointerHazardous(
    std::uintptr_t instructionPointer, const PatchHazardRange* ranges,
    DWORD rangeCount) noexcept
{
    for (DWORD index = 0; index < rangeCount; ++index) {
        if (instructionPointer >= ranges[index].begin &&
            instructionPointer < ranges[index].end) return true;
    }
    if (g_module != nullptr) {
        __try {
            const auto* base = reinterpret_cast<const unsigned char*>(g_module);
            const auto* dos = reinterpret_cast<const IMAGE_DOS_HEADER*>(base);
            const auto* nt = reinterpret_cast<const IMAGE_NT_HEADERS32*>(
                base + dos->e_lfanew);
            const std::uintptr_t moduleBegin =
                reinterpret_cast<std::uintptr_t>(base);
            const std::uintptr_t moduleEnd = moduleBegin +
                nt->OptionalHeader.SizeOfImage;
            if (dos->e_magic == IMAGE_DOS_SIGNATURE &&
                nt->Signature == IMAGE_NT_SIGNATURE &&
                instructionPointer >= moduleBegin &&
                instructionPointer < moduleEnd) return true;
        } __except (MemoryProbeExceptionFilter(GetExceptionCode())) {
            return true;
        }
    }
    return false;
}

bool suspendOtherThreadsForPatchTransaction(
    const PatchHazardRange* ranges, DWORD rangeCount,
    PatchThreadTransaction* transaction,
    bool requireNoActiveHooks) noexcept
{
    if (transaction == nullptr ||
        (rangeCount != 0 && ranges == nullptr)) return false;
    *transaction = PatchThreadTransaction{};
    DWORD stablePasses = 0;
    for (DWORD pass = 0; pass < 8u && stablePasses < 2u; ++pass) {
        HANDLE snapshot = CreateToolhelp32Snapshot(TH32CS_SNAPTHREAD, 0);
        if (snapshot == INVALID_HANDLE_VALUE) {
            resumePatchThreadTransaction(transaction);
            return false;
        }
        THREADENTRY32 entry{};
        entry.dwSize = sizeof(entry);
        BOOL hasEntry = Thread32First(snapshot, &entry);
        if (hasEntry == FALSE) {
            CloseHandle(snapshot);
            resumePatchThreadTransaction(transaction);
            return false;
        }
        DWORD added = 0;
        for (;;) {
            if (entry.th32OwnerProcessID == GetCurrentProcessId() &&
                entry.th32ThreadID != GetCurrentThreadId() &&
                entry.th32ThreadID != g_flushThreadId) {
                bool known = false;
                for (DWORD index = 0; index < transaction->count; ++index) {
                    if (transaction->ids[index] == entry.th32ThreadID) {
                        known = true;
                        break;
                    }
                }
                if (!known) {
                    if (transaction->count >= _countof(transaction->handles)) {
                        CloseHandle(snapshot);
                        resumePatchThreadTransaction(transaction);
                        return false;
                    }
                    HANDLE thread = OpenThread(THREAD_SUSPEND_RESUME |
                        THREAD_GET_CONTEXT | THREAD_QUERY_INFORMATION,
                        FALSE, entry.th32ThreadID);
                    if (thread != nullptr) {
                        const DWORD previous = SuspendThread(thread);
                        if (previous == static_cast<DWORD>(-1)) {
                            CloseHandle(thread);
                            CloseHandle(snapshot);
                            resumePatchThreadTransaction(transaction);
                            return false;
                        }
                        CONTEXT context{};
                        context.ContextFlags = CONTEXT_CONTROL;
                        if (GetThreadContext(thread, &context) == FALSE ||
                            patchInstructionPointerHazardous(
                                static_cast<std::uintptr_t>(context.Eip),
                                ranges, rangeCount)) {
                            ResumeThread(thread);
                            CloseHandle(thread);
                            CloseHandle(snapshot);
                            resumePatchThreadTransaction(transaction);
                            return false;
                        }
                        const DWORD slot = transaction->count++;
                        transaction->handles[slot] = thread;
                        transaction->ids[slot] = entry.th32ThreadID;
                        ++added;
                    } else if (GetLastError() != ERROR_INVALID_PARAMETER) {
                        CloseHandle(snapshot);
                        resumePatchThreadTransaction(transaction);
                        return false;
                    }
                }
            }
            SetLastError(ERROR_SUCCESS);
            if (Thread32Next(snapshot, &entry) == FALSE) {
                const DWORD enumerationError = GetLastError();
                CloseHandle(snapshot);
                if (enumerationError != ERROR_NO_MORE_FILES) {
                    resumePatchThreadTransaction(transaction);
                    return false;
                }
                break;
            }
        }
        stablePasses = added == 0 ? stablePasses + 1u : 0u;
        SwitchToThread();
    }
    if (stablePasses < 2u ||
        (requireNoActiveHooks &&
         InterlockedCompareExchange(&g_activeHooks, 0, 0) != 0)) {
        resumePatchThreadTransaction(transaction);
        return false;
    }
    return true;
}

